<?php
require_once __DIR__.'/db.php';
require_once __DIR__.'/auth.php';
require_roles(['Admin', 'HR']);
function e($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
$month=$_GET['month']??date('Y-m');if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$month))$month=date('Y-m');
$st=$conn->prepare("SELECT id,employee_code,full_name,department,designation,salary,status FROM employees WHERE status='Active' ORDER BY department,full_name");$st->execute();$res=$st->get_result();$employees=[];$total=0;while($r=$res->fetch_assoc()){$employees[]=$r;$total+=(float)$r['salary'];}$st->close();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payroll | HRMS</title><link rel="stylesheet" href="assets.css"></head><body><header><h1>Payroll overview</h1><p>Monthly salary register · estimates only</p></header><?php include 'nav.php';?><main><div class="page-head"><div><h2>Payroll register</h2><p>Active employees and their configured monthly base salary.</p></div><form method="get" style="display:flex;gap:8px;align-items:center"><input type="month" name="month" value="<?=e($month)?>"><button class="btn" type="submit">View month</button></form></div><div class="grid"><section class="panel col-4"><div class="muted">Active employees</div><div class="number"><?=count($employees)?></div></section><section class="panel col-4"><div class="muted">Monthly base salary total</div><div class="number" style="font-size:28px!important">₹<?=number_format($total,2)?></div></section><section class="panel col-4"><div class="muted">Selected period</div><div class="number" style="font-size:28px!important"><?=e(date('F Y',strtotime($month.'-01')))?></div></section><section class="panel col-12"><h3>Salary register</h3><p class="muted">This is not a payslip or statutory payroll calculation. It excludes attendance deductions, tax, PF/ESI, bonuses and reimbursements.</p><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Department</th><th>Designation</th><th>Monthly base</th><th>Annualized base</th></tr></thead><tbody><?php foreach($employees as $emp):?><tr><td><strong><?=e($emp['full_name'])?></strong><br><small><?=e($emp['employee_code'])?></small></td><td><?=e($emp['department'])?></td><td><?=e($emp['designation'])?></td><td>₹<?=number_format((float)$emp['salary'],2)?></td><td>₹<?=number_format((float)$emp['salary']*12,2)?></td></tr><?php endforeach;?><?php if(!$employees):?><tr><td colspan="5">No active employees found.</td></tr><?php endif;?></tbody><tfoot><tr><th colspan="3">Total monthly base</th><th>₹<?=number_format($total,2)?></th><th>₹<?=number_format($total*12,2)?></th></tr></tfoot></table></div><button class="btn" onclick="window.print()" type="button">Print register</button></section></div></main><style>@media print{header,.navrow,form,button{display:none!important}body{background:white!important}.panel{box-shadow:none!important;border:0!important}main{max-width:none!important;margin:0!important}}</style></body></html>
